def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    def is_expired(write_time, current_time):
        return write_time + ttl <= current_time

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries (this helps with eviction decisions)
            expired_keys = [k for k, (_, wt) in cache.items() if is_expired(wt, t)]
            for k in expired_keys:
                del cache[k]

            # If key exists, remove it to re-add at end (most recently used)
            if key in cache:
                del cache[key]
            # If cache is full and key is new, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove oldest (least recently used)

            # Add the new entry
            cache[key] = (value, t)
            # Move to end to mark as most recently used
            cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache:
                value, write_time = cache[key]
                if is_expired(write_time, t):
                    # Expired, treat as absent
                    results.append(-1)
                else:
                    # Valid entry, mark as most recently used
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

    return results

